$activeTab=$this->input->get('tab',true)?:'permit'; if(!in_array($activeTab,['permit','exit','delivery','complete'],true))$activeTab='permit';
function sdf_date_ok($v){if(!$v)return '-';if(is_numeric($v)&&(int)$v>1000000000)return date('Y-m-d',(int)$v);if(preg_match('/^(\d{4}-\d{2}-\d{2})/',trim($v),$m))return $m[1];return html_escape($v);}
function sdf_addr($c){return trim(implode('، ',array_filter([$c['address']??'',$c['city']??'',$c['state']??'',$c['zip']??''])));}
?>
